From d1077b41a1b514117772d5d383c392a3b120155f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:08:26 +0100
Subject: [PATCH] containments/desktop: make icon cells tall enough for the
 label font

Icon cells reserved one grid unit per label line, but the grid unit does
not follow the font size, so with a bigger font two-line labels made the
highlight overflow into the item below. Use the font's line height too.

BUG: 514581
---
 containments/desktop/package/contents/ui/FolderView.qml | 8 +++++++-
 1 file changed, 7 insertions(+), 1 deletion(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..5bee1b2a9a 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -709,6 +709,11 @@ FocusScope {
                     id: horizontalScrollBar
                 }

+                FontMetrics {
+                    id: labelFontMetrics
+                    font: Kirigami.Theme.defaultFont
+                }
+
                 function calcExtraSpacing(cellSize, containerSize) {
                     const availableColumns = Math.floor(containerSize / cellSize);
                     let extraSpacing = 0;
@@ -742,7 +747,8 @@ FocusScope {
                             listItemSvg.margins.top + listItemSvg.margins.bottom)) / 2) * 2;
                     } else {
                         // the smallSpacings are for padding
-                        const iconHeight = iconSize + (Kirigami.Units.gridUnit * Plasmoid.configuration.textLines) + (Kirigami.Units.smallSpacing * 3);
+                        const lineHeight = Math.max(Kirigami.Units.gridUnit, Math.ceil(labelFontMetrics.height));
+                        const iconHeight = iconSize + (lineHeight * Plasmoid.configuration.textLines) + (Kirigami.Units.smallSpacing * 3);
                         if (root.isContainment && isRootView && scrollArea.viewportHeight > 0) {
                             let extraHeight = calcExtraSpacing(iconHeight, scrollArea.viewportHeight);
                             return iconHeight + extraHeight;
-- 
